/**
 *
 * Sidebar is a layout component for building application navigation.
 *
 * [Live Demo](https://www.primereact.org/sidebar/)
 *
 * @module Sidebar
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { UseSidebarExposes, UseSidebarProps, UseSidebarState } from '@primereact/types/headless/sidebar';
/**
 * Defines passthrough(pt) options type in SidebarLayout component.
 */
export type SidebarLayoutPassThroughType<E> = PassThroughType<SidebarLayoutInstance, E>;
/**
 * Defines passthrough(pt) options of SidebarLayout component.
 */
export interface SidebarLayoutPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: SidebarLayoutPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in SidebarLayout component.
 */
export interface SidebarLayoutProps extends BaseComponentProps<SidebarLayoutInstance, object, SidebarLayoutPassThrough> {
}
/**
 * Instance of SidebarLayout component.
 */
export type SidebarLayoutInstance = ComponentInstance<SidebarLayoutProps, object, object>;
/**
 * Defines passthrough(pt) options type in SidebarRoot component.
 */
export type SidebarRootPassThroughType<E> = PassThroughType<SidebarRootInstance, E>;
/**
 * Defines passthrough(pt) options of SidebarRoot component.
 */
export interface SidebarRootPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: SidebarRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in SidebarRoot component.
 */
export interface SidebarRootProps extends BaseComponentProps<SidebarRootInstance, UseSidebarProps, SidebarRootPassThrough> {
}
/**
 * Defines valid state in SidebarRoot component.
 */
export interface SidebarRootState extends UseSidebarState {
}
/**
 * Defines the methods and properties exposed by SidebarRoot component.
 */
export interface SidebarRootExposes extends UseSidebarExposes {
}
/**
 * Instance of SidebarRoot component.
 */
export type SidebarRootInstance = ComponentInstance<SidebarRootProps, SidebarRootState, SidebarRootExposes>;
